// Package adtgen regenerates the compiler's own ADTs — the Go packages
// generated by gomgo from the Go copies of the Gom ADT files kept in
// src/go/tom (gom/adt: the AST of Gom, used by gomgo itself; engine/adt
// and engine/adt/il: the AST of the Tom compiler). They are generated as
// any other Gom module (gomgo gom-batch, backend.GenerateBatchToDir):
// one <module>.go per .gom file and the Tom mapping <pkg>.tom of the
// package. When the package has hooks written in Tom+Go (construction
// hooks, rules: they are host code of the mapping), a Tom file of the
// package that includes the mapping (Hooks, e.g. hooks.t) is compiled
// by `tom -go` into hooks.go, which installs them when the package is
// initialised — as the hooks of a %gom block are installed by the Tom
// file that holds the block.
//
// Used by the regenadt command (mage RegenAdt) and by the regeneration
// tests, which require the committed packages to be byte-identical to a
// fresh regeneration.
package adtgen

import (
	"bytes"
	"fmt"
	"go/format"
	"os"
	"os/exec"
	"path/filepath"
	"sort"
	"strings"

	gomast "tom/gom/adt"
	"tom/gom/backend"
	gomparser "tom/gom/parser"
)

// ADT describes one generated package. Paths are relative to the root of
// module tom (src/go/tom).
type ADT struct {
	Dir   string   // directory of the .gom files and of the generated package
	Out   string   // directory of the generated package (default: Dir)
	Pkg   string   // Go package name
	Files []string // the .gom files, relative to Dir, in generation order
	// Hooks is the Tom+Go file of the package (relative to Dir) that
	// includes the mapping, compiled by tom -go into hooks.go; "" when
	// the package has no Tom+Go hook.
	Hooks string
}

// OutDir returns the directory of the generated package.
func (a ADT) OutDir() string {
	if a.Out != "" {
		return a.Out
	}
	return a.Dir
}

// ADTs are the compiler's ADTs: the Go copies of src/tom/gom/adt/*.gom
// and src/tom/engine/adt/*.gom. As in build.xml (one gomcompile per
// unit), Il.gom is generated alone, into engine/adt/il (its operator
// subterm and the Subterm of Code.gom would have the same Go name).
var ADTs = []ADT{
	{
		Dir:   "gom/adt",
		Pkg:   "adt",
		Files: []string{"Code.gom", "Gom.gom", "Objects.gom", "Rule.gom", "SymbolTable.gom"},
	},
	{
		Dir: "engine/adt",
		Pkg: "adt",
		Files: []string{"CST.gom", "Code.gom", "Theory.gom", "TomConstraint.gom", "TomDeclaration.gom",
			"TomExpression.gom", "TomInstruction.gom", "TomName.gom", "TomOption.gom", "TomSignature.gom",
			"TomSlot.gom", "TomTerm.gom", "TomType.gom", "TypeConstraints.gom"},
		Hooks: "hooks.t",
	},
	{
		Dir:   "engine/adt",
		Out:   "engine/adt/il",
		Pkg:   "il",
		Files: []string{"Il.gom"},
	},
}

// HooksGo is the file tom -go writes the hooks into.
const HooksGo = "hooks.go"

// hooksHeader starts hooks.go.
const hooksHeader = "// Code generated by tom -go from %s (it includes the mapping %s.tom). DO NOT EDIT.\n\n"

// Tools locates the Tom distribution used to compile the hooks.
type Tools struct {
	TomHome string // TOM_HOME of a built distribution (bin/tom)
}

// Generate generates the package of a into a new directory under tmp
// (root is the root of module tom) and returns the generated files:
// published name → content.
func Generate(root string, a ADT, tools Tools, tmp string) (map[string][]byte, error) {
	var mods []gomast.GomModule
	for _, f := range a.Files {
		m, err := gomparser.ParseFile(filepath.Join(root, a.Dir, f))
		if err != nil {
			return nil, err
		}
		mods = append(mods, m)
	}
	out, err := os.MkdirTemp(tmp, "adtgen-")
	if err != nil {
		return nil, err
	}
	if _, err := backend.GenerateBatchToDir(mods, backend.Options{PackageName: a.Pkg}, out); err != nil {
		return nil, err
	}
	files := map[string][]byte{}
	entries, err := os.ReadDir(out)
	if err != nil {
		return nil, err
	}
	for _, e := range entries {
		if e.Name() == "go.mod" {
			continue // gom-batch writes a stand-alone module; the ADTs live in module tom
		}
		b, err := os.ReadFile(filepath.Join(out, e.Name()))
		if err != nil {
			return nil, err
		}
		files[e.Name()] = b
	}
	if a.Hooks != "" {
		hooks, err := compileHooks(root, a, tools, out)
		if err != nil {
			return nil, err
		}
		files[HooksGo] = hooks
	}
	return files, nil
}

// compileHooks compiles the hooks file of a, next to the generated
// mapping in out, with tom -go, and returns the gofmt'd Go code.
func compileHooks(root string, a ADT, tools Tools, out string) ([]byte, error) {
	src, err := os.ReadFile(filepath.Join(root, a.Dir, a.Hooks))
	if err != nil {
		return nil, err
	}
	stub := filepath.Join(out, a.Hooks)
	if err := os.WriteFile(stub, src, 0o644); err != nil {
		return nil, err
	}
	tomOut := filepath.Join(out, "tom-out")
	cmd := exec.Command(filepath.Join(tools.TomHome, "bin", "tom"), "-go", "-d", tomOut, a.Hooks)
	cmd.Dir = out
	cmd.Env = append(os.Environ(), "TOM_HOME="+tools.TomHome)
	if b, err := cmd.CombinedOutput(); err != nil {
		return nil, fmt.Errorf("tom -go %s: %v\n%s", a.Hooks, err, b)
	}
	gen, err := os.ReadFile(filepath.Join(tomOut, strings.TrimSuffix(a.Hooks, ".t")+".go"))
	if err != nil {
		return nil, err
	}
	gen = append([]byte(fmt.Sprintf(hooksHeader, a.Hooks, a.Pkg)), gen...)
	formatted, err := format.Source(gen)
	if err != nil {
		return nil, fmt.Errorf("gofmt of the code tom -go generated from %s: %v", a.Hooks, err)
	}
	return formatted, nil
}

// IsGenerated reports whether a file of a package directory is
// generated (and must therefore be byte-identical to a regeneration):
// a .go file starting with a "Code generated" header, or a .tom mapping.
func IsGenerated(name string, content []byte) bool {
	switch {
	case strings.HasSuffix(name, "_test.go"):
		return false
	case strings.HasSuffix(name, ".go"):
		return bytes.HasPrefix(content, []byte("// Code generated "))
	case strings.HasSuffix(name, ".tom"):
		return true
	}
	return false
}

// Diff compares a regeneration (files) with the package directory dir:
// it returns the names of the generated files that differ, are missing
// or are no longer generated.
func Diff(dir string, files map[string][]byte) ([]string, error) {
	var out []string
	for name, want := range files {
		got, err := os.ReadFile(filepath.Join(dir, name))
		if err != nil || !bytes.Equal(got, want) {
			out = append(out, name)
		}
	}
	entries, err := os.ReadDir(dir)
	if err != nil {
		return nil, err
	}
	for _, e := range entries {
		if e.IsDir() {
			continue
		}
		if _, ok := files[e.Name()]; ok {
			continue
		}
		b, err := os.ReadFile(filepath.Join(dir, e.Name()))
		if err != nil {
			return nil, err
		}
		if IsGenerated(e.Name(), b) {
			out = append(out, e.Name()+" (no longer generated)")
		}
	}
	sort.Strings(out)
	return out, nil
}

// Write writes the generated files into dir, removing the generated
// files that are no longer generated.
func Write(dir string, files map[string][]byte) error {
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return err
	}
	stale, err := Diff(dir, files)
	if err != nil {
		return err
	}
	for _, s := range stale {
		if name, ok := strings.CutSuffix(s, " (no longer generated)"); ok {
			if err := os.Remove(filepath.Join(dir, name)); err != nil {
				return err
			}
		}
	}
	for name, b := range files {
		if err := os.WriteFile(filepath.Join(dir, name), b, 0o644); err != nil {
			return err
		}
	}
	return nil
}
